expectPoint("top", () => bindingPoint(rect, { x: 50, y: -200 }), { x: 50, y: 0 });
expectPoint("bottom", () => bindingPoint(rect, { x: 50, y: 200 }), { x: 50, y: 100 });
expectPoint("corner", () => bindingPoint(rect, { x: 150, y: 150 }), { x: 100, y: 100 });

console.log("ellipse binding:");
