expectPoint("ellipse right", () => bindingPoint(wide, { x: 500, y: 50 }), { x: 200, y: 50 });
expectPoint("ellipse bottom", () => bindingPoint(wide, { x: 100, y: 300 }), { x: 100, y: 100 });

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed === 0 ? 0 : 1);

